// Proposed src/lib/copy/tokens.ts (R2: notOwned removed, have/haveOn added, Generated by, In Shopping, Copy note removed, details block → line).
// Earlier: (R1). Placeholders until /copy-review.
// Voice is refresh.ts's: labels and figures, every count with its noun, no verdict words.
// Reused unchanged: priceCopy.tag.*, priceCopy.strip.*, exportLinkOutCopy.shopping, recommendationsCopy.shopping group styles.

const n = (x: number) => x.toLocaleString("en-US");
const cards = (x: number) => (x === 1 ? "1 card" : `${n(x)} cards`);
const tokens = (x: number) => (x === 1 ? "1 token" : `${n(x)} tokens`);

export const tokensCopy = {
  group: {
    label: "Tokens",
    /** Header note (desktop) / sub-line (phone). Says once that tokens aren't the deck. */
    note: (makers: number) => `not in the 99 · from ${cards(makers)}`,
    noteOnlyCopy: "not in the 99 · no token card to list",
    noteFailed: "not in the 99",
    failed: "Tokens couldn’t be read just now.",
  },

  /** Open question 1: no token-read marker yet (lock 5). Said once, at the head. */
  unknown: {
    body: "Your collection hasn’t been read for tokens yet. Press I have one on the ones you own, or upload your collection again and they’ll be read from it.",
    action: "Upload your collection",
  },

  row: {
    type: (type: string, pt: string | null) => (pt ? `${type} · ${pt}` : type),
    from: (first: string, count: number) => (count === 1 ? `from ${first}` : `from ${first} and ${n(count - 1)} more`),
    /** Ownership facts. Never a verdict word, never --warning. Unknown draws nothing. */
    owned: "in your collection",
    join: "Add to Shopping",
    joined: "✓ In Shopping",
    /** Manual ownership (R2). Held state is the same record an upload writes, source "manual". */
    have: "I have one",
    haveOn: "✓ I have one",
    haveAria: (name: string) => `Mark the ${name} token as in your collection`,
    haveOffAria: (name: string) => `Unmark the ${name} token`,
    joinAria: (name: string) => `Add the ${name} token to this deck’s Shopping list`,
    leaveAria: (name: string) => `Take the ${name} token off this deck’s Shopping list`,
    toggleAria: (name: string, count: number) => `${name} token, made by ${cards(count)}`,
  },

  makers: {
    label: (count: number) => `Generated by ${cards(count)}`,
    scrolls: "A–Z · scrolls",
    /** Open question 3: the representative printing, by the deck price rule. */
    printing: (code: string, cost: string, printings: number) =>
      `pictured and sent: ${code} · ${cost} · cheapest of ${n(printings)} ${printings === 1 ? "printing" : "printings"}`,
    noMaker: "from no card in this deck",
  },

  shopping: {
    clause: (count: number) => `${n(count)} · not in the deck’s count`,
    sub: (typeLine: string, code: string | null) => (code ? `token · ${typeLine} · ${code}` : `token · ${typeLine}`),
    removeAria: (name: string) => `Take the ${name} token off Shopping`,
  },

  strip: {
    line: (count: number, cost: string) => `+ ${tokens(count)} · ${cost}`,
    lineNoPrice: (count: number) => `+ ${tokens(count)}`,
    deckNone: "Nothing to buy for the deck",
    /** R2: the box's split line under the figure. */
    split: (cardN: number, cardCost: string, tokenN: number, tokenCost: string) =>
      cardN === 0 ? `${tokens(tokenN)} · nothing for the deck` : `${cards(cardN)} · ${cardCost}  ·  ${tokens(tokenN)} · ${tokenCost}`,
    sends: (cardLines: number, tokenLines: number) =>
      cardLines === 0
        ? `Opens Mana Pool with ${n(tokenLines)} token ${tokenLines === 1 ? "line" : "lines"}, each with its set and number, so none can be read as a card.`
        : `Opens Mana Pool with ${n(cardLines)} card lines and ${n(tokenLines)} token ${tokenLines === 1 ? "line" : "lines"}. Cards send names and quantities; tokens send set and number.`,
  },

  /** R2: one line at the foot of card details' In this deck box. No block of its own. */
  details: {
    line: (names: string[]) => (names.length === 1 ? `Makes a ${names[0]} token` : `Makes ${names.slice(0, -1).join(", ")} and ${names[names.length - 1]} tokens`),
    inShopping: "In Shopping",
    owned: "in your collection",
    link: "Tokens ›",
  },
} as const;
